export type IconName = keyof typeof ICONS;

export function DuoIcon({
  name,
  size = 24,
  className = "",
  duo = "#185FA5",
  duoOpacity = 0.85,
  title,
}: {
  name: IconName;
  size?: number;
  className?: string;
  /** colour of the duotone layer (brand blue by default) */
  duo?: string;
  duoOpacity?: number;
  title?: string;
}) {
  const icon = ICONS[name];
  return (
    <svg
      viewBox="0 0 256 256"
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
    >
      {icon.duo && <path d={icon.duo} fill={duo} opacity={duoOpacity} />}
      <path d={icon.line} />
    </svg>
  );
}
